save(339,dict(paragraphs=["Matralina Pati is a poet, researcher and translator working between Bengali and English. Her literary biographies describe research into marginal Bhasha literatures in English translation at Bankura University. She translated Rudra Pati’s Bengali poems for ‘Monsoon Seems Promising This Year’, bringing another poet’s work into conversation with her own writing.","Her Kabita Live poems question what can be measured and what remains concealed. ‘The Insoluble Sum’ turns calculation into an image of life’s resistance to explanation; the accompanying ‘Deaths and the Accountant’ sharpens that image into a critique of reducing lives to accounts. ‘Bubbles within’ gives loss a fragile, vanishing form, while ‘Matrimony’ contrasts public vows with a truth kept out of sight."],sources=[source('Literary Vibes: Matralina Pati contributor biography','https://positivevibes.today/article/newsview/742',['Bankura research affiliation, marginal Bhasha literature research and translation work.']),source('Setu: Matralina Pati','https://www.setumag.com/2025/03/poetry-matralina-pati.html',['Bilingual poet and translator; Monsoon Seems Promising This Year.']),source('Mascara Literary Review: Monsoon Seems Promising This Year','https://www.mascarareview.com/nithya-sam-reviews-monsoon-seems-promising-this-year-by-rudra-pati-translated-by-matralina-pati/',['Rudra Pati original poet; Matralina Pati English translator; Tristoop publication.']),source('Bankura University: second convocation lists, 2025','https://www.bankurauniv.ac.in/uploads/tempimagepdflink/1760369046.pdf',['Identity corroboration: English 2018–2020 first class first matches captured educational biography; not treated as PhD completion.'])],books=[dict(title='Monsoon Seems Promising This Year',detail='Rudra Pati’s Bengali poetry · English translation by Matralina Pati · Read the review',url='https://www.mascarareview.com/nithya-sam-reviews-monsoon-seems-promising-this-year-by-rudra-pati-translated-by-matralina-pati/')],identity_match='Distinctive name, Bankura English research and 2020 academic result match captured record; literary biographies and translation review agree.',poems_read=[dict(id=418,title='The Insoluble Sum',basis='Full original including separate internal heading Deaths and the Accountant: two texts under one catalogue contribution; arithmetic, ledger and loss.'),dict(id=520,title='Bubbles within',basis='Full original: wilting bubbles, lost self, estrangement; no personal medical inferences.'),dict(id=751,title='Matrimony',basis='Full original: names, vows and havan contrasted with concealed truth.')],limitations=['Composite poem record 418 retained exactly; no reclassification or poem-count change. Translation book not misattributed as original authorship. No inferred health history.'],next_action='Independent factual review and editorial review of composite source structure.'))
